const fs = require('node:fs');
const { createClient } = require('./client');
const { importOrders } = require('./order-importer');

async function main() {
  const args = process.argv.slice(2);
  const scenarios = { success: 'ok', transient: 'transient', auth: 'auth', ambiguous: 'ambiguous', unknown: 'unknown' };
  const scenario = args.length === 0 ? 'success' : args[1];
  if ((args.length !== 0 && (args.length !== 2 || args[0] !== '--scenario')) || !Object.hasOwn(scenarios, scenario)) {
    throw Object.assign(new Error('Unsupported arguments'), { code: 'USAGE' });
  }
  let rows;
  try { rows = JSON.parse(fs.readFileSync(0, 'utf8')); }
  catch { throw Object.assign(new Error('Invalid JSON input'), { code: 'INPUT_JSON' }); }
  const result = await importOrders(rows, createClient([scenarios[scenario]]));
  process.stdout.write(`${JSON.stringify(result)}\n`);
}

main().catch((error) => {
  process.stderr.write(`${JSON.stringify({ error: { code: error.code, message: error.message } })}\n`);
  process.exitCode = 1;
});
'use strict';

function failure(code, message) {
  return Object.assign(new Error(message), { code });
}

function createClient(outcomes = []) {
  let attempts = 0;
  const applied = [];
  return {
    get attempts() { return attempts; },
    get applied() { return applied.slice(); },
    async send(rows) {
      const outcome = outcomes[attempts++] || 'ok';
      if (!Array.isArray(rows) || rows.some((row) => !row || typeof row.id !== 'string' || !row.id.trim())) {
        throw failure('INVALID_ORDER', 'Invalid order rows');
      }
      if (outcome === 'transient') throw failure('TRANSIENT_BEFORE_SEND', 'Request not sent');
      if (outcome === 'auth') throw failure('AUTH_FAILED', 'Access denied');
      if (outcome === 'unknown') throw failure('UNCLASSIFIED', 'Unclassified failure');
      applied.push(...rows.map((row) => row.id));
      if (outcome === 'ambiguous') throw failure('OUTCOME_UNKNOWN', 'Response unavailable');
      return { imported: rows.length };
    },
  };
}

module.exports = { createClient };
'use strict';

function importOrders(rows, client) {
  return client.send(rows);
}

module.exports = { importOrders };
